// `rules` instead, and should move there when it appears.
//
// A local pack: declared by hand as `local/laughcounter`, never fingerprinted
// (detect/marker null).
export default {
  id: 'laughcounter',
  detect: null,
  marker: null,
  prose: 'RULES.md',
  rules: [],
};

